/* Rekening koran satu rekening operasional. Aritmetikanya NYATA:
     saldo awal 900.000.000 + kredit 328.000.000 - debit 503.179.000
     = saldo akhir 724.821.000
   Satu baris - biaya transfer SKN, baris 6 - sengaja dicetak dengan saldo
   berjalan yang salah ketik 10.000. Saldo akhirnya tetap benar, persis seperti
   ekspor bank sungguhan yang kolom saldonya kadang meleset. Pemeriksaan
   integritas harus menangkap baris itu tanpa menganggap seluruh mutasi rusak. */
function hari(n){ const d=new Date(); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); }
const AWAL = 900000000;
const b = [
 [ -5, 'TRF MASUK INV-7002',        'INV-7002',    'PT SUMBER REJEKI ABADI',   0,         180000000 ],
 [ -5, 'PEMBAYARAN VENDOR',          'TRX-REC-001', 'PT SINAR BAJA ELEKTRIK',   8584800,   0 ],
 [ -5, 'BIAYA ADMIN BULANAN',        'ADM-0911',    'BANK MANDIRI',             6500,      0 ],
 [ -4, 'PELUNASAN TAGIHAN',          'PLN-0912',    'CV ANUGERAH TEKNIK',       0,         30500000 ],
 [ -4, 'PEMBAYARAN VENDOR',          'TRX-REC-002', 'PT ANUGERAH METALINDO',    480000000, 0 ],
 [ -4, 'BIAYA TRANSFER SKN',         'SKN-0912',    'BANK MANDIRI',             2900,      0 ],
 [ -3, 'TRF MASUK INV-7006',         'INV-7006',    'UD SINAR TERANG',          0,         10000000 ],
 [ -3, 'PEMBAYARAN VENDOR',          'TRX-REC-003', 'CV BERKAH JAYA MANDIRI',   6000000,   0 ],
 [ -2, 'TRF MASUK INV-7005',         'INV-7005',    'BENGKEL KARYA MANDIRI',    0,         5000000 ],
 [ -2, 'TRANSFER',                   'TRF-88213',   'PT MAKMUR SEJAHTERA',      0,         7500000 ],
 [ -2, 'PEMBAYARAN VENDOR',          'TRX-REC-001', 'PT SINAR BAJA ELEKTRIK',   8584800,   0 ],
 [ -1, 'TRF MASUK INV-7007',         'INV-7007',    'PT GLOBAL NIAGA PERSADA',  0,         95000000 ],
];
let saldo = AWAL;
const akhir = b.reduce(function(s,x){ return s - x[4] + x[5]; }, AWAL);
return b.map(function(x, i){
  saldo = saldo - x[4] + x[5];
  const cetak = (i === 5) ? saldo + 10000 : saldo;   /* baris 6: salah ketik saldo */
  return { json: {
    line_key: 'STM-' + hari(0).split('-').join('') + '-' + String(i+1).padStart(3,'0'),
    statement_id: 'STM-' + hari(0).split('-').join(''),
    account_code: 'OPS-IDR-01', line_no: i+1, value_date: hari(x[0]),
    description: x[1], reference: x[2], counterparty: x[3],
    debit: x[4], credit: x[5], running_balance: cetak,
    opening_balance: AWAL, closing_balance: akhir
  }};
});

/* Empat baris pembayaran yang dicocokkan terhadap debit di rekening koran.
   Masing-masing menguji satu hal:
     TRX-REC-001  lunas, ada di mutasi               - cocok
     TRX-REC-002  lunas, ada di mutasi               - cocok
     TRX-REC-003  DITOLAK bank, tapi mutasi mendebet - uang keluar padahal katanya gagal
     TRX-REC-004  lunas, TIDAK ADA di mutasi         - katanya terbayar, uangnya tak pernah keluar
   Dua yang terakhir adalah alasan rekonsiliasi ada. */
function hari(n){ const d=new Date(); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); }
const p = [
 ['Sinar Baja Elektrik',      'INV-REC-01', 8760000,   175200, 'settled',  'TRX-REC-001', '', -5],
 ['Anugerah Metalindo',       'INV-REC-02', 480000000, 0,      'settled',  'TRX-REC-002', '', -4],
 ['Berkah Jaya Mandiri',      'INV-REC-03', 6000000,   0,      'rejected', 'TRX-REC-003', 'rekening tujuan sudah ditutup', -3],
 ['Mitra Logistik Nusantara', 'INV-REC-04', 50400000,  0,      'settled',  'TRX-REC-004', '', -3],
];
return p.map(function(x){ return { json: {
  line_key: 'REC-DEMO|' + x[0].toUpperCase() + '|' + x[1], run_key: 'REC-DEMO',
  vendor: x[0], invoice_number: x[1], amount: x[2], currency: 'IDR',
  status: x[4], route_to: 'accounting_auto', hold_code: '', hold_reason: '',
  account_number_masked: '******0000', pay_on: hari(x[7]), discount_taken: x[3],
  bank_ref: x[5], settled_on: x[4]==='settled' ? hari(x[7]) : '', reject_reason: x[6],
  execution_id: 'seed'
}};});
